-- Balsam Fir
INSERT INTO molecules (name, family, chemicalFormula, olfactiveProfile, emotionalResonance, functionalEffect, sourceOrigin, concentration, notes, molecularWeight, boilingPoint, volatility, intensity, complexity, botanicalSources, extractionMethod, therapeuticProperties, radar_intensity, radar_freshness, radar_warmth, radar_sweetness, radar_spiciness, radar_earthiness)
VALUES ('Balsam Fir Essential Oil', 'Huile Essentielle', 'C12H20O2 (bornyl acétate)', 'Balsamique doux, résineux avec des notes de miel et de forêt enneigée', 'Nostalgie des fêtes, chaleur familiale, pureté hivernale', 'Accord sapin, notes festives, base naturelle', 'Vermont, Maine, Québec', '100%', 'Source du baume du Canada. Récolte hivernale traditionnelle.', 196, 225, 55, 65, 70, 'Abies balsamea - Forêts de Nouvelle-Angleterre et Québec', 'Distillation à la vapeur des aiguilles', 'Expectorant, antiseptique, cicatrisant', 65, 70, 50, 55, 25, 55);

-- Black Spruce
INSERT INTO molecules (name, family, chemicalFormula, olfactiveProfile, emotionalResonance, functionalEffect, sourceOrigin, concentration, notes, molecularWeight, boilingPoint, volatility, intensity, complexity, botanicalSources, extractionMethod, therapeuticProperties, radar_intensity, radar_freshness, radar_warmth, radar_sweetness, radar_spiciness, radar_earthiness)
VALUES ('Black Spruce Essential Oil', 'Huile Essentielle', 'C12H20O2 (bornyl acétate)', 'Balsamique intense, notes de résine et de terre froide, profondeur boréale', 'Immensité de la taïga, solitude contemplative, force tranquille', 'Base boréale, accord taïga, notes terreuses', 'Québec, Ontario Nord, Labrador', '100%', 'Espèce emblématique de la forêt boréale canadienne.', 196, 225, 50, 80, 75, 'Picea mariana - Forêt boréale canadienne', 'Distillation à la vapeur des aiguilles', 'Tonifiant surrénalien, immunostimulant', 80, 65, 40, 30, 35, 80);

-- Ponderosa Pine
INSERT INTO molecules (name, family, chemicalFormula, olfactiveProfile, emotionalResonance, functionalEffect, sourceOrigin, concentration, notes, molecularWeight, boilingPoint, volatility, intensity, complexity, botanicalSources, extractionMethod, therapeuticProperties, radar_intensity, radar_freshness, radar_warmth, radar_sweetness, radar_spiciness, radar_earthiness)
VALUES ('Ponderosa Pine', 'Huile Essentielle', 'C10H16 (α-pinène, β-pinène)', 'Vanille distinctive, résine chaude, notes de butterscotch et de caramel', 'Chaleur des montagnes Rocheuses, après-midi ensoleillé en altitude', 'Notes vanillées uniques, chaleur boisée', 'Colorado, Montana, Wyoming', '100%', 'Écorce caractéristique sentant la vanille et le butterscotch.', 136, 155, 70, 60, 85, 'Pinus ponderosa - Montagnes Rocheuses', 'Distillation à la vapeur de l écorce', 'Antiseptique, expectorant, tonifiant', 60, 50, 75, 70, 30, 55);

-- Rocky Mountain Juniper
INSERT INTO molecules (name, family, chemicalFormula, olfactiveProfile, emotionalResonance, functionalEffect, sourceOrigin, concentration, notes, molecularWeight, boilingPoint, volatility, intensity, complexity, botanicalSources, extractionMethod, therapeuticProperties, radar_intensity, radar_freshness, radar_warmth, radar_sweetness, radar_spiciness, radar_earthiness)
VALUES ('Rocky Mountain Juniper', 'Huile Essentielle', 'C10H16 (α-pinène, sabinène)', 'Genévrier épicé, notes de gin, boisé sec et légèrement sucré', 'Paysages arides des hauts plateaux, spiritualité amérindienne', 'Notes épicées, accord genévrier, fraîcheur sèche', 'Colorado, Utah, Nouveau-Mexique', '100%', 'Récolte sauvage en altitude. Utilisé par les peuples autochtones.', 136, 155, 75, 70, 70, 'Juniperus scopulorum - Montagnes Rocheuses', 'Distillation à la vapeur des baies', 'Diurétique, antiseptique urinaire', 70, 65, 55, 40, 70, 60);

-- Birch Tar
INSERT INTO molecules (name, family, chemicalFormula, olfactiveProfile, emotionalResonance, functionalEffect, sourceOrigin, concentration, notes, molecularWeight, boilingPoint, volatility, intensity, complexity, botanicalSources, extractionMethod, therapeuticProperties, radar_intensity, radar_freshness, radar_warmth, radar_sweetness, radar_spiciness, radar_earthiness)
VALUES ('Birch Tar North American', 'Goudron / Absolu', 'Composés phénoliques', 'Notes de goudron de bouleau, cuiré, fumé et légèrement sucré', 'Traditions ancestrales, feux de camp nordiques, authenticité brute', 'Accord cuir, notes fumées, profondeur animale', 'Québec, Maine, Minnesota', '10% dilution', 'Goudron de bouleau obtenu par pyrolyse traditionnelle.', NULL, NULL, 25, 90, 95, 'Betula papyrifera - Forêts boréales', 'Pyrolyse de l écorce', 'Antiseptique, cicatrisant', 90, 20, 65, 35, 45, 85);

-- Labrador Tea
INSERT INTO molecules (name, family, chemicalFormula, olfactiveProfile, emotionalResonance, functionalEffect, sourceOrigin, concentration, notes, molecularWeight, boilingPoint, volatility, intensity, complexity, botanicalSources, extractionMethod, therapeuticProperties, radar_intensity, radar_freshness, radar_warmth, radar_sweetness, radar_spiciness, radar_earthiness)
VALUES ('Labrador Tea Essential Oil', 'Huile Essentielle', 'Sesquiterpènes complexes', 'Herbacé complexe, notes de miel sauvage et de résine, légèrement camphré', 'Tourbières boréales, solitude des grands espaces, mystère nordique', 'Notes herbacées originales, accord boréal unique', 'Québec, Labrador, Alaska', '100%', 'Récolte sauvage en tourbières. Plante des Premières Nations.', 204, 260, 45, 75, 90, 'Rhododendron groenlandicum - Tourbières boréales', 'Distillation à la vapeur des feuilles', 'Hépatoprotecteur, anti-inflammatoire', 75, 55, 45, 50, 40, 70);

